import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/corpus/gen_block-scalars.mjs';
let s = readFileSync(p, 'utf8');
const NUL = '�';
console.log('has literal NUL:', s.includes(NUL));
const weird = [...new Set([...s].filter((ch) => ch.charCodeAt(0) > 126 || ch.charCodeAt(0) < 9))];
console.log('non-ascii/ctrl chars:', JSON.stringify(weird.map((c) => c.codePointAt(0).toString(16))));
// replace the literal NUL inside the guard with a proper escape
s = s.split("c.includes('" + NUL + "')").join("c.includes('\\u0000')");
// replace literal non-ascii content chars with \u escapes
const map = {
  'é': '\\u00e9',
  'è': '\\u00e8',
  'ü': '\\u00fc',
  '日': '\\u65e5',
  '本': '\\u672c',
  '語': '\\u8a9e',
};
for (const [k, v] of Object.entries(map)) s = s.split(k).join(v);
writeFileSync(p, s);
console.log('patched');

import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/corpus/gen_block-scalars.mjs';
let s = readFileSync(p, 'utf8');
const lines = s.split('\n');
lines.forEach((ln, i) => {
  const bad = [...ln].filter((ch) => {
    const c = ch.codePointAt(0);
    return c > 126 || c < 9 || (c > 10 && c < 32);
  });
  if (bad.length) {
    console.log(
      i + 1,
      JSON.stringify(bad.map((c) => 'U+' + c.codePointAt(0).toString(16).toUpperCase())),
      '||',
      JSON.stringify(ln)
    );
  }
});

import { readFileSync, writeFileSync } from 'node:fs';
const p = '/workspace/probe/corpus/gen_block-scalars.mjs';
let s = readFileSync(p, 'utf8');
const lines = s.split('\n');
const repl = {
  208: "  '|\\n  a\\u00a0b\\n',",
  209: "  '|-\\n  a\\u2028b\\n',",
  210: "  '>\\n  a\\u0085b\\n',",
};
for (const [idx, val] of Object.entries(repl)) {
  const i = Number(idx);
  const has = [...lines[i]].some((ch) => {
    const c = ch.codePointAt(0);
    return c > 126 || c < 9 || (c > 10 && c < 32);
  });
  if (!has) throw new Error(`line ${i + 1} does not hold the expected literal char: ${lines[i]}`);
  lines[i] = val;
}
writeFileSync(p, lines.join('\n'));
console.log('escaped 3 lines');

import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/block-scalars';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0,
  err = 0;
const show = new Set(process.argv.slice(2));
for (const f of files) {
  const inp = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc;
  try {
    out = execFileSync(EXE, ['--a', inp], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    rc = 0;
    ok++;
  } catch (e) {
    out = (e.stdout || '') + (e.stderr || '');
    rc = e.status;
    err++;
  }
  if (show.size === 0 || show.has(f)) {
    console.log(`##### ${f} rc=${rc}`);
    console.log('  IN : ' + JSON.stringify(inp));
    console.log('  OUT: ' + JSON.stringify(out));
  }
}
console.log(`\ntotal=${files.length} rc0=${ok} rcNonZero=${err}`);
